'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { parse, CsvError } = require('../src/csv');

const err = (text, opts, line, column) =>
  assert.throws(() => parse(text, opts), (e) => e instanceof CsvError && e.line === line && e.column === column);

test('basics', () => {
  assert.deepStrictEqual(parse(''), []);
  assert.deepStrictEqual(parse('a,b\r\nc,d\ne,f\rg,h'), [['a', 'b'], ['c', 'd'], ['e', 'f'], ['g', 'h']]);
  assert.deepStrictEqual(parse('﻿a,b\n'), [['a', 'b']]);
  assert.deepStrictEqual(parse('a;b', { delimiter: ';' }), [['a', 'b']]);
  assert.deepStrictEqual(parse(' a , b '), [[' a ', ' b ']]);
  assert.deepStrictEqual(parse('a,'), [['a', '']]);
});
test('quotes', () => {
  assert.deepStrictEqual(parse('"a,b","c""d","e\r\nf"\n'), [['a,b', 'c"d', 'e\r\nf']]);
  assert.deepStrictEqual(parse('a"b,c'), [['a"b', 'c']]);
  assert.deepStrictEqual(parse('""'), [['']]);
});
test('empty lines', () => {
  assert.deepStrictEqual(parse('a\n\nb\n'), [['a'], [''], ['b']]);
  assert.deepStrictEqual(parse('a\n\n'), [['a'], ['']]);
  assert.deepStrictEqual(parse('\n'), [['']]);
  assert.deepStrictEqual(parse('a\n\n\nb', { skipEmptyLines: true }), [['a'], ['b']]);
  assert.deepStrictEqual(parse('""\n', { skipEmptyLines: true }), [['']]);
});
test('header mode', () => {
  assert.deepStrictEqual(parse('a,b\n1,2\n', { header: true }), [{ a: '1', b: '2' }]);

