'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { parse, stringify } = require('../src/csv');

const rows = [[''], ['a'], [' '], ['', ''], ['"'], ['x,y', 'z\r\nw', '\n'], ['é😀', ' p ', '\r']];
test('round trip with all option combinations', () => {
  for (const eol of ['\r\n', '\n']) for (const delimiter of [',', ';', '\t']) for (const skipEmptyLines of [false, true]) {
    const o = { eol, delimiter, skipEmptyLines };
    assert.deepStrictEqual(parse(stringify(rows, o), o), rows);
  }
});
test('header round trip', () => {
  const out = stringify([{ a: 'x', b: 'y' }], { header: ['a', 'b'] });
  assert.deepStrictEqual(parse(out, { header: true }), [{ a: 'x', b: 'y' }]);
});

