'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { stringify } = require('../src/csv');

test('basics and quoting', () => {
  assert.strictEqual(stringify([]), '');
  assert.strictEqual(stringify([['a', 1, true, null, undefined]]), 'a,1,true,,\r\n');
  assert.strictEqual(stringify([['a,b', 'c"d', 'e\nf', ' g', 'h ']], { eol: '\n' }), '"a,b","c""d","e\nf"," g","h "\n');
  assert.strictEqual(stringify([['']]), '""\r\n');
  assert.strictEqual(stringify([['a;b', 'c,d']], { delimiter: ';' }), '"a;b";c,d\r\n');
});
test('header objects', () => {
  assert.strictEqual(stringify([{ a: 1 }, ['x', 'y']], { header: ['a', 'b'], eol: '\n' }), 'a,b\n1,\nx,y\n');
});
test('errors', () => {
  assert.throws(() => stringify('x'), TypeError);
  assert.throws(() => stringify([[{}]]), TypeError);
  assert.throws(() => stringify([[1n]]), TypeError);
  assert.throws(() => stringify([['a']], { eol: '\r' }), TypeError);
  assert.throws(() => stringify([['a']], { delimiter: '"' }), TypeError);
  assert.throws(() => stringify([{ a: 1 }]), TypeError);
});

